import { retryDelay, retryCost, retryBudget } from './src/retry.ts';
import { estimatedWait, waitLabel, pendingAllowance } from './src/delivery.ts';

console.log('retryDelay(0) =', retryDelay(0), '(expect 0.05 s)');
console.log('retryDelay(1) =', retryDelay(1), '(expect 0.1 s)');
console.log('retryDelay(2) =', retryDelay(2), '(expect 0.2 s)');
console.log('retryDelay(8) =', retryDelay(8), '(expect 10 s, capped)');
console.log('retryDelay(4,urgent) =', retryDelay(4, 2, 'urgent'), '(expect 0.5 s, urgent cap)');
console.log('estimatedWait(0) =', estimatedWait(0), '(expect 50 ms)');
console.log('estimatedWait(8) =', estimatedWait(8), '(expect 10000 ms)');
console.log('waitLabel(0) =', waitLabel(0), '(expect "50ms")');
console.log('waitLabel(2) =', waitLabel(2), '(expect "200ms")');
console.log('retryCost(0) =', retryCost(0), '(expect 50 ms)');
console.log('retryCost(8) =', retryCost(8), '(expect 10000 ms)');
console.log('retryBudget(0).wait =', retryBudget(0).wait, '(expect 0.05 s)');
console.log('retryBudget(0).remaining =', retryBudget(0).remaining, '(expect 6)');
console.log('pendingAllowance(2) =', pendingAllowance(2), '(expect 4)');

import assert from 'node:assert/strict';
import { DeliveryLedger } from './src/delivery.ts';

// due must stay in ms: attempt 1 -> 100ms delay, attempt 2 -> 200ms delay
const ledger = new DeliveryLedger(6);
ledger.enqueue({ sequence: 1, topic: 't', payload: {} }, ['s']);
ledger.failure(1, 's', 0, 'boom');
// due = 100ms -> not ready at 99ms
assert.equal(ledger.ready(99).length, 0, 'should not be ready before due');
assert.equal(ledger.ready(100).length, 1, 'should be ready at due=100ms');

// second failure schedules attempt 2 -> 200ms
ledger.failure(1, 's', 100, 'boom');
assert.equal(ledger.ready(299).length, 0, 'not ready before 200ms delay');
assert.equal(ledger.ready(300).length, 1, 'ready at 100+200=300ms');

// urgent queue cap -> 500ms
const { retryDelay } = await import('./src/retry.ts');
assert.equal(retryDelay(9, 2, 'urgent') * 1000, 500, 'urgent cap 500ms');
assert.equal(retryDelay(9, 2, 'standard') * 1000, 10000, 'standard cap 10000ms');

console.log('timing assertions OK');

